using System;using System.IO;using System.Reflection;using UnityEngine;using EchoSphere.Presentation;public static class NetworkNoCrossbarCheck{const BindingFlags F=BindingFlags.Static|BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;public static object Main(){var a=typeof(NativeHudView).Assembly;var st=a.GetType("EchoSphere.Presentation.NativeWorldSurface");var nt=a.GetType("EchoSphere.Presentation.NativeWorldNetwork");var node=nt.GetNestedType("Node",F);var link=nt.GetNestedType("Link",F);var network=nt.GetNestedType("Network",F);var formation=nt.GetNestedType("Formation",F);object Call(object o,string n,params object[] args)=>o.GetType().GetMethod(n,F).Invoke(o,args);void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);var go=new GameObject("Owned vertical formation render");var surface=go.AddComponent(st);var renderer=Activator.CreateInstance(nt,true);int checks=0;try{Call(surface,"Initialize");Call(surface,"SetViewport",360f,300f,1f);var data=Activator.CreateInstance(network);var points=Array.CreateInstance(node,3);for(int i=0;i<3;i++){var p=Activator.CreateInstance(node);Set(p,"X",0d);Set(p,"Y",(i-1)*90d);points.SetValue(p,i);}var links=Array.CreateInstance(link,3);int[] from={0,1,0},to={1,2,2};for(int i=0;i<3;i++){var p=Activator.CreateInstance(link);Set(p,"A",from[i]);Set(p,"B",to[i]);links.SetValue(p,i);}var line=Activator.CreateInstance(formation);Set(line,"Nodes",new[]{0,1,2});Set(line,"Active",true);Set(data,"NodeCount",3);Set(data,"Spheres",points);Set(data,"Links",links);Set(data,"Line",line);var optional=Array.CreateInstance(typeof(Nullable<>).MakeGenericType(node),0);var external=Array.CreateInstance(link,0);for(int frame=0;frame<2;frame++){Call(surface,"Begin",Vector2.zero);Call(surface,"ResetTransform");Call(renderer,"BeginFrame");Call(renderer,"Draw",surface,data,optional,external,frame*.4d);Call(surface,"End");var rt=(RenderTexture)st.GetProperty("UiTexture",F).GetValue(surface);var old=RenderTexture.active;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);try{RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();var pixels=image.GetPixels32();int lit=0,outside=0;for(int y=0;y<rt.height;y++)for(int x=0;x<rt.width;x++){var p=pixels[y*rt.width+x];if(p.b<=8||p.a<=4)continue;lit++;if(Math.Abs(x-rt.width*.5f)>12)outside++;}checks++;if(lit<100||outside>0)throw new Exception("vertical formation: lit="+lit+" crossbar pixels="+outside);if(frame==1)File.WriteAllBytes("Library/boss-sphere-push/line-no-crossbar.png",image.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(image);}}var result=new{status="PASS",checks,scope="actual GPU vertical formation, normal links deduplicated and comet motion, no detached horizontal marker; no save writes"};File.WriteAllText("Library/boss-sphere-push/line-no-crossbar.json",Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;}finally{((IDisposable)renderer).Dispose();UnityEngine.Object.DestroyImmediate(go);}}}